-- Atomic rollout control; normal operation remains on UUID version 1.
create schema if not exists private;
create table private.identifier_control(singleton boolean primary key default true check(singleton), version integer not null check(version in (1,2)), maintenance boolean not null default false);
alter table private.identifier_control enable row level security;
insert into private.identifier_control(singleton,version) values(true,1);
revoke all on private.identifier_control from public,anon,authenticated;
grant usage on schema private to service_role;
grant select on private.identifier_control to service_role;
create function public.identifier_schema_state() returns jsonb language sql stable security invoker set search_path='' as $$ select jsonb_build_object('version',version,'maintenance',maintenance) from private.identifier_control where singleton $$;
revoke all on function public.identifier_schema_state() from public,anon,authenticated;
grant execute on function public.identifier_schema_state() to service_role;
create function private.guard_identifier_rollout() returns trigger language plpgsql security definer set search_path='' as $$ begin
if coalesce(current_setting('clearpath.identifier_migration',true),'')<>'approved' and exists(select 1 from private.identifier_control where singleton and maintenance) then raise exception 'identifier_maintenance'; end if;
if tg_op='DELETE' then return old; end if; return new; end $$;
revoke all on function private.guard_identifier_rollout() from public,anon,authenticated;
create trigger identifier_maintenance before insert or update or delete on public.activities for each row execute function private.guard_identifier_rollout();
create trigger identifier_maintenance before insert or update or delete on public.alert_events for each row execute function private.guard_identifier_rollout();
create trigger identifier_maintenance before insert or update or delete on public.announcements for each row execute function private.guard_identifier_rollout();
